{
  "what_i_checked_on_my_side": {
    "identified_line": {
      "customer_id": "C1001",
      "phone_number": "555-123-2002",
      "line_id": "L1002",
      "status": "Active",
      "roaming_enabled_on_account": true,
      "plan": {
        "plan_id": "P1002",
        "name": "Premium Plan",
        "data_limit_gb": 15,
        "refuel_price_per_gb": 2.0
      },
      "usage_this_cycle": {
        "used_gb": 8.7,
        "refueled_gb": 0.0,
        "remaining_gb": 6.3,
        "cycle_ends_on": "2025-02-28"
      }
    },
    "implication": "Your account and line look good: it’s active, roaming is enabled on our side, and you haven’t hit your data limit. That points to phone settings/network conditions while roaming as the likely cause of slow/no data."
  },
  "next_steps_on_your_phone": [
    {
      "step": "Check overall network status",
      "how": "Run check_network_status and share the readout (airplane mode, signal strength bars, network type 5G/4G/3G/2G, mobile data ON/OFF, data roaming ON/OFF).",
      "why": "Confirms the basics needed for fast roaming data."
    },
    {
      "step": "Ensure Data Roaming is ON",
      "how": "If check_network_status shows data roaming OFF, turn it ON using toggle_roaming.",
      "why": "While abroad, mobile data won’t work reliably unless data roaming is enabled on the phone."
    },
    {
      "step": "Set fastest network mode",
      "how": "Run check_network_mode_preference. If it isn’t already 4g_5g_preferred, set it using set_network_mode_preference to \"4g_5g_preferred\".",
      "why": "Ensures your phone uses the fastest available network where you are roaming."
    },
    {
      "step": "Confirm Mobile Data and Data Saver",
      "how": "From check_network_status verify Mobile Data is ON; if OFF, use toggle_data to turn it ON. Then run check_data_restriction_status; if Data Saver is ON, turn it OFF with toggle_data_saver_mode.",
      "why": "Data Saver or the main data switch can throttle or block data."
    },
    {
      "step": "Check VPN",
      "how": "Run check_vpn_status; if a VPN is connected, disconnect it with disconnect_vpn.",
      "why": "VPNs often reduce speed or cause timeouts, especially while roaming."
    },
    {
      "step": "Quick network refresh",
      "how": "Toggle Airplane Mode ON for 10 seconds, then OFF using toggle_airplane_mode.",
      "why": "Forces the phone to re-register on the best local partner network."
    },
    {
      "step": "Speed test",
      "how": "Run run_speed_test on mobile data and share the result label (very poor/poor/fair/good/excellent) and any Mbps shown.",
      "why": "Verifies actual performance after the changes."
    },
    {
      "step": "APN sanity check (only if still slow/no data)",
      "how": "Run check_apn_settings. If APN shows incorrect/missing values, reset with reset_apn_settings, then immediately run reboot_device.",
      "why": "Incorrect APN can cause slow/no data; a reset plus reboot restores defaults."
    },
    {
      "step": "If 5G seems unstable while roaming",
      "how": "If speeds fluctuate or drop to no data on 5G, temporarily set set_network_mode_preference to \"4g_only\" and retest with run_speed_test.",
      "why": "Some roaming areas have patchy 5G; 4G-only can deliver more consistent high speeds."
    }
  ],
  "what_to_reply_back_with": [
    "The city/area in France where you are right now.",
    "The full output of check_network_status (airplane mode, signal strength, network type, mobile data, data roaming).",
    "The current network mode from check_network_mode_preference.",
    "Whether Data Saver or a VPN was ON and what you set them to.",
    "Speed test result label and approximate download speed.",
    "APN check result (and whether you reset + rebooted, if applicable)."
  ],
  "notes": [
    "Roaming is already enabled on your line from our side at no cost.",
    "You have ~6.3 GB remaining this cycle. If you need more, I can add up to 2 GB instantly at $2/GB with your approval.",
    "Once you share the results above, I’ll advise the exact next action to get you to excellent speed if possible in your current location."
  ]
}

