messages.content:
{
  "what_i_already_fixed_on_your_account": {
    "roaming": "Enabled on your 555-123-2002 line (required abroad).",
    "data_remaining": "You have ~6.3 GB left this cycle, so you’re not capped."
  },
  "why_you_have_no_connection_right_now": [
    "Airplane Mode is ON: this disables all cellular radios, so there’s no signal.",
    "Network mode is 2G only: 2G is too slow for modern data and often won’t pass data at all.",
    "Data Saver is ON: can throttle/limit background data.",
    "VPN is ON: can slow or block traffic, especially when roaming."
  ],
  "do_this_now_on_your_samsung_galaxy_s22": [
    {
      "step": "Turn OFF Airplane Mode",
      "path": "Quick Settings shade → tap Airplane icon to turn it OFF (or Settings → Connections → Airplane mode → OFF)",
      "why": "Restores cellular radios so the phone can see towers."
    },
    {
      "step": "Disconnect VPN",
      "path": "Settings → Connections → More connection settings → VPN → tap your VPN → Disconnect",
      "why": "Avoids VPN-related slowdowns/blocks while we test raw network speed."
    },
    {
      "step": "Turn OFF Data Saver",
      "path": "Settings → Connections → Data usage → Data saver → OFF",
      "why": "Prevents OS from restricting data."
    },
    {
      "step": "Set Network Mode to 5G/LTE (auto)",
      "path": "Settings → Connections → Mobile networks → Network mode (SIM) → 5G/LTE/3G/2G (auto connect)",
      "why": "Lets the phone use the fastest available network instead of 2G."
    },
    {
      "step": "Refresh the connection",
      "path": "Toggle Mobile Data OFF then ON (Settings → Connections → Data usage → Mobile data), then wait 15–30 seconds. If you still don’t see bars, reboot the phone.",
      "why": "Forces a fresh registration to the roaming network."
    }
  ],
  "then_check": [
    "Look at the status bar: how many signal bars do you see? Does it show 5G/LTE/4G?",
    "Try a speed test and tell me the result category (unknown/very poor/poor/fair/good/excellent)."
  ],
  "if_speed_is_not_excellent_after_that": [
    {
      "option": "Try 4G-only temporarily",
      "path": "Settings → Connections → Mobile networks → Network mode → LTE/4G only (if available)",
      "why": "Sometimes 5G roaming can be unstable; 4G may be faster and steadier."
    },
    {
      "option": "Reset APN to default, then reboot",
      "path": "Settings → Connections → Mobile networks → Access Point Names → ⋮ (menu) → Reset to default → Reboot phone",
      "why": "Fixes incorrect APN/MMSC values that can block/throttle data."
    },
    {
      "option": "Reseat the SIM if there’s still no signal",
      "path": "Power off → eject SIM tray → reinsert SIM securely → power on",
      "why": "Ensures the SIM makes proper contact for roaming registration."
    }
  ],
  "reminders": [
    "Roaming is enabled on your line at no cost.",
    "You currently have ample high‑speed data remaining."
  ],
  "please_reply_with": [
    "What you see in the status bar now (bars and network type: 5G/LTE/4G).",
    "Speed test result category.",
    "If any step above wasn’t available on your menus."
  ]
}

