messages.content:
{
  "summary": "I’ve found your account and line, confirmed you’re on a 15 GB plan with 8.7 GB used (so you haven’t hit your data cap), and your line is Active. Because you’re in France, I enabled international data roaming on your line ending in 2002. MMS needs working mobile data while roaming, so next we’ll make sure your phone itself is set up to use roaming data and that MMS settings (APN/MMSC) are correct.",
  "what_i_did_and_why": [
    "Identified your line 555-123-2002 and verified status: Active, plan limit not reached. This rules out suspension and data-cap blockage.",
    "Account-level roaming was OFF, which would block data abroad; I enabled roaming on your line so the network allows data in France."
  ],
  "next_steps_on_your_phone": [
    {
      "step": "Check overall network state",
      "why": "Confirms Airplane Mode, signal, data, and roaming toggles.",
      "do_this": [
        "Run check_status_bar() and check_network_status().",
        "Share the results for: Airplane Mode, signal strength, network type (e.g., 4G/5G), Mobile Data status, and Data Roaming status."
      ],
      "manual_hint": "Settings > Network/Connections > Mobile network: make sure Airplane Mode is OFF, Mobile Data is ON."
    },
    {
      "step": "Enable Data Roaming on the phone (if OFF)",
      "why": "Even with roaming enabled on your account, your phone must also allow data while abroad.",
      "do_this": [
        "If check_network_status() shows Roaming OFF, turn it ON using toggle_roaming()."
      ],
      "manual_hint": "Settings > Network & Internet (or Connections) > Mobile network > Data roaming = ON."
    },
    {
      "step": "Temporarily prefer mobile data for the test",
      "why": "Some devices/carriers do not deliver MMS reliably over Wi‑Fi/Wi‑Fi Calling.",
      "do_this": [
        "Run check_wifi_calling_status(); if ON, use toggle_wifi_calling() to turn it OFF.",
        "Use toggle_wifi() to turn Wi‑Fi OFF for the test."
      ]
    },
    {
      "step": "Verify network mode",
      "why": "2G/3G can break MMS; we want 4G/5G.",
      "do_this": [
        "Run check_network_mode_preference(). If it shows 2G or 3G, use set_network_mode_preference(\"4g_5g_preferred\")."
      ]
    },
    {
      "step": "Check APN/MMSC for MMS",
      "why": "A missing or wrong MMSC URL prevents MMS.",
      "do_this": [
        "Run check_apn_settings(). If MMSC URL is missing/incorrect, use reset_apn_settings() then reboot_device()."
      ],
      "note": "A reboot is required after resetting APN."
    },
    {
      "step": "Eliminate VPN/data saver conflicts",
      "why": "VPNs and Data Saver can block/slow MMS.",
      "do_this": [
        "Run check_vpn_status(); if a VPN is connected, use disconnect_vpn().",
        "Run check_data_restriction_status(); if Data Saver is ON, use toggle_data_saver_mode() to turn it OFF for this test."
      ]
    },
    {
      "step": "Messaging app permissions",
      "why": "The app needs Storage and SMS permissions to send media.",
      "do_this": [
        "Run check_app_permissions(app_name=\"messaging\"). If Storage or SMS are not granted, use grant_app_permission(\"messaging\", \"storage\") and grant_app_permission(\"messaging\", \"sms\")."
      ]
    },
    {
      "step": "Test MMS",
      "why": "Confirm fix.",
      "do_this": [
        "With Wi‑Fi OFF and Mobile Data + Data Roaming ON, send a small photo MMS to your own number.",
        "Tell me what happens (e.g., sends successfully, still stuck on “sending”, or error)."
      ]
    }
  ],
  "please_share_back": [
    "Output of check_network_status() and check_status_bar().",
    "Whether Data Roaming was OFF and if you turned it ON.",
    "Whether Wi‑Fi Calling was ON and if you turned it OFF, and that Wi‑Fi is OFF for the test.",
    "Result of check_apn_settings() (specifically whether an MMSC URL is present).",
    "Your MMS test result after these steps."
  ]
}

