messages.content:
{
  "message": "I can help. “No Service” usually means either the phone is blocking radios (airplane mode), the SIM isn’t being read, network settings are off, or the line might be suspended. I’ll check your account/line status and guide you through quick device checks so we cover both sides.",
  "request_for_identification": "To look up your line, please provide one of the following:\n- The phone number on the affected SIM (preferred)\n- Or your customer ID\n- Or your full name and date of birth (YYYY-MM-DD)",
  "quick_questions": [
    "Are you currently traveling outside your usual area or internationally?",
    "Did this start suddenly today, and did you recently change SIM/eSIM or transfer to a new phone?",
    "Have you already tried a full restart of the phone?"
  ],
  "guided_device_checks": [
    {
      "step": "Check the status bar",
      "why": "Confirms if airplane mode is on, whether there are signal bars, and shows the network type.",
      "how": "Look at the top of the screen and tell me what you see: airplane icon, bars (none/1-4), and network tech (5G/4G/3G/2G)."
    },
    {
      "step": "Make sure Airplane Mode is OFF",
      "why": "If it’s ON, all cellular service is disabled.",
      "how": "Open quick settings and toggle Airplane Mode OFF. If it was on, wait 10–15 seconds after turning it off."
    },
    {
      "step": "Check SIM status",
      "why": "If the phone doesn’t detect the SIM, you’ll see No Service.",
      "how": "If your phone shows ‘No SIM’ or ‘SIM locked’, let me know. If removable SIM: power off, remove the SIM, reinsert carefully, then power on."
    },
    {
      "step": "Ensure mobile data and a modern network mode",
      "why": "Data/calls require cellular enabled and at least 4G/5G for best connectivity.",
      "how": "In Settings > Network/Cellular: make sure Mobile Data is ON; set Network Mode to 4G/5G preferred if available."
    },
    {
      "step": "Reset APN (if needed)",
      "why": "Incorrect APN can break connectivity.",
      "how": "If you’ve customized APN before, reset to default in Mobile Network > Access Point Names, then reboot the device."
    },
    {
      "step": "Reboot the phone",
      "why": "Refreshes the radio and applies network changes.",
      "how": "Restart and check if service returns."
    }
  ],
  "next_actions": "Please share the affected phone number (or other ID) and the results of steps 1–3. I’ll immediately check your line status (including any suspension or roaming settings) and continue with the fastest fix based on what you report."
}

