  "steps": [
    {
      "step": "Enable Data Roaming on the phone",
      "how_to_android_generic": "Settings > Network & Internet (or Connections) > Mobile network > Data Roaming > ON",
      "notes": "Wording varies slightly by device. You can turn it off again later if needed; it won’t erase anything."
    },
    {
      "step": "Wait ~15 seconds after enabling",
      "reason": "Gives the phone time to register roaming data with the local network."
