      "step": "Optional quick refresh",
      "how": "Toggle Mobile Data OFF then ON once, if available."
    },
    {
      "step": "Test MMS",
      "how": "With Wi‑Fi still OFF, send one picture message to a single contact. If possible, also try a second contact to rule out a recipient-side issue."
    },
    {
      "step": "Confirm data works",
      "how": "Open your browser and load a website with Wi‑Fi still OFF.",
      "reason": "Verifies roaming data is actually active."
    }
