messages.content:
{
  "message": "You’re not doing anything wrong—this is a common roaming setup issue. Your line is active and has data available. Since Data Roaming is now ON and you see strong 5G, the next likely culprits are a device setting (VPN, Wi‑Fi Calling, Data Saver) or APN/MMSC configuration. We’ll check those in order.",
  "steps": [
    {
      "title": "Confirm roaming data actually works",
      "do": "With Wi‑Fi still OFF, open your browser and load any website (e.g., example.com).",
      "why": "If web browsing fails, mobile data isn’t usable yet, which would also block MMS."
    },
    {
      "title": "Make sure no VPN is active",
      "do": "Check the status bar for a small key icon. If present: Settings > Network & Internet (or Connections) > VPN > Disconnect.",
      "why": "Some VPNs prevent MMS from reaching the carrier’s MMS server."
    },
    {
      "title": "Turn OFF Wi‑Fi Calling (for this test)",
      "do": "Settings > Network & Internet (or Connections) > Mobile network > Wi‑Fi Calling > OFF.",
      "why": "While traveling, Wi‑Fi Calling can sometimes interfere with MMS routing—even if Wi‑Fi is off."
    },
    {
      "title": "Turn OFF Data Saver",
      "do": "Settings > Network & Internet > Data Saver > OFF.",
      "why": "Data Saver can restrict background data that MMS depends on."
    },
    {
      "title": "Test MMS again",
      "do": "With Wi‑Fi still OFF and Data Roaming ON, send one picture to a single contact (optionally try a second contact).",
      "why": "Confirms whether any of the above resolved it."
    },
    {
      "title": "If it still fails: Reset APN to default, then reboot",
      "do": "Settings > Network & Internet (or Connections) > Mobile Network > Access Point Names (APN) > menu (⋮) > Reset to default. Then restart the phone.",
      "important": "This does not delete personal data/photos. After reboot, ensure Mobile Data and Data Roaming are ON and Wi‑Fi is OFF, then test MMS again.",
      "why": "An incorrect or missing MMSC in the APN is a very common MMS blocker when roaming. Reset + reboot reapplies correct settings."
    },
    {
      "title": "If needed: Check messaging app permissions",
      "do": "Settings > Apps > Your messaging app (Messages, etc.) > Permissions > ensure Storage/Photos and SMS are Allowed.",
      "why": "The app needs these to attach and send media."
    }
  ],
  "questions": [
    "With Wi‑Fi off, could you load a website?",
    "Do you see a VPN key icon? If so, did disconnecting it help?",
    "After turning off Wi‑Fi Calling and Data Saver, did the picture send?",
    "If you reset APN and rebooted, what happened when you tried again?"
  ],
  "note": "If any step is unclear for your specific Android menu layout, tell me the options you see and I’ll map you through it."
}

