        {
          "action": "reset_apn_settings",
          "instructions": "If APN looks incorrect or MMSC is missing, run reset_apn_settings.",
          "reason": "Restores the correct carrier APN values."
        },
        {
          "action": "reboot_device",
          "instructions": "After resetting APN, run reboot_device.",
          "reason": "Applies APN changes and refreshes network services."
        },
        {
          "action": "run_speed_test",
          "instructions": "After reboot, keep Wi‑Fi OFF and run run_speed_test again. Share the result label.",
          "reason": "Checks if data connectivity is restored."
        }
      ]
    },
    {
      "condition": "If there is still no connection after the APN reset and reboot",
      "steps": [
        {
          "action": "check_network_mode_preference",
          "instructions": "Run check_network_mode_preference and tell me what it shows.",
          "reason": "Ensures your device prefers modern networks."
        },
        {
          "action": "set_network_mode_preference",
          "instructions": "If it shows 2G/3G or anything older, set set_network_mode_preference to \"4g_5g_preferred\".",
          "reason": "Allows connection to 4G/5G for proper data service."
        },
        {
          "action": "check_data_restriction_status",
          "instructions": "Run check_data_restriction_status and report if Data Saver or background data restrictions are ON.",
          "reason": "These can block or throttle data.",
          "follow_up": {
            "action": "toggle_data_saver_mode",
            "instructions": "If Data Saver is ON, run toggle_data_saver_mode to turn it OFF."
          }
        },
        {
          "action": "check_vpn_status",
          "instructions": "Run check_vpn_status and report if a VPN is active/connected.",
          "reason": "VPNs can interfere with connectivity.",
          "follow_up": {
            "action": "disconnect_vpn",
            "instructions": "If a VPN is connected, run disconnect_vpn."
          }
        },
        {
          "action": "run_speed_test",
          "instructions": "Run run_speed_test again and share the result label.",
          "reason": "Re-checks connectivity after adjustments."
        }
      ]
    }
  ],
  "what_i_will_do_next_on_our_side": "Once you share the next results (starting with check_network_status), I will identify the specific line on your account that maps to 555-123-2002 and check its status and current data usage to rule out any plan or account limits, then proceed accordingly.",
  "request": "Please start with check_network_status now and share its full output. Then run run_speed_test and let me know the result label. If the speed test still shows no connection, continue with the APN steps and report back what you see."
}

