messages.content:
{
  "explanation": "I can help. “No Service” is usually caused by one of three things: (1) a device setting like Airplane Mode or a SIM issue, (2) incorrect phone network settings, or (3) an account/line status problem (e.g., suspension). I’ll first identify your account and line status, then walk you through quick checks on the phone to restore service.",
  "what_i_will_do_next": [
    "Verify your account and the affected line’s status (to rule out any suspension or provisioning issues).",
    "If the line is OK, guide you through targeted device checks: Airplane Mode, SIM status, and network settings.",
    "If needed, try safe resets (toggle radios/reboot) and check APN settings."
  ],
  "information_needed_from_you": {
    "required_for_lookup": "Please provide the phone number of the affected line.",
    "alternative_if_no_phone_number": "If you don’t have the number handy, share your full name and date of birth (YYYY-MM-DD) for verification.",
    "context_questions": [
      "City/State where you’re currently located (helps determine if this could be area-specific).",
      "Do other lines on your account or nearby people on the same carrier also have no service?",
      "Is your device using a physical SIM or an eSIM?",
      "Any recent changes (new phone/SIM/eSIM transfer, plan change, travel, or software update)?"
    ]
  },
  "quick_checks_you_can_start_now": [
    {
      "step": "Check Airplane Mode",
      "how": "Look at the top status bar for an airplane icon, or open quick settings. If ON, turn it OFF. If already OFF, toggle Airplane Mode ON for 10 seconds, then OFF to refresh the radios.",
      "why": "Airplane Mode disables all cellular radios and is a very common cause of “No Service.”"
    },
    {
      "step": "Look at the status bar and report what you see",
      "how": "Tell me if you see any signal bars, “No Service,” or network type indicators like 5G/4G/LTE.",
      "why": "This helps confirm whether the phone is registering on the network at all."
    },
    {
      "step": "Check SIM status",
      "how": "On Android: Settings > Network & Internet > SIMs (or Mobile Network) and confirm the SIM shows as Active/Ready. On iPhone: Settings > Cellular > confirm your line shows as On and a network is displayed. Tell me if it says Missing, Inactive, or Locked.",
      "why": "A missing or locked SIM prevents any network connection."
    },
    {
      "step": "Confirm Mobile Data is enabled (even though calls also fail)",
      "how": "Android: Settings > Network & Internet > SIMs/Mobile Network > Mobile data = On. iPhone: Settings > Cellular > Cellular Data = On.",
      "why": "While calls use the cellular network, this confirms the device isn’t globally restricting cellular connectivity."
    },
    {
      "step": "If nothing changes after the above, perform a reboot",
      "how": "Restart the phone normally.",
      "why": "A reboot refreshes all radios and clears temporary glitches."
    }
  ],
  "what_to_reply_with": "Please send me the affected phone number (or full name + DOB), your city/state, whether other lines are affected, whether you use a physical SIM or eSIM, any recent changes, and the results of steps 1–3. I’ll start by checking your line status as soon as I have your identification."
}

