messages.content:
{
  "explanation": "Your line is Active now, so the remaining “No Signal/Data Disabled” is most likely a device-side registration/SIM issue. Let’s verify the SIM is recognized, ensure mobile data isn’t switched off, and confirm the network mode so your phone can register on the tower.",
  "steps": [
    {
      "step": "Check SIM status",
      "why": "If the SIM is missing or locked, the phone cannot register to the network.",
      "ios": "Settings > Cellular. Tap your line; confirm it shows On/Active and a carrier name. Note if it says No SIM, SIM Locked, or similar.",
      "android": "Settings > Network & Internet (or Connections) > SIMs/Mobile Network. Confirm the SIM shows Active/Ready. Note if it says Missing, Inactive, or Locked.",
      "tell_me": "Report exactly what it says (Active/Ready, Missing/No SIM, or Locked)."
    },
    {
      "step": "Turn Mobile Data ON",
      "why": "Ensures the device isn’t blocking cellular data registration.",
      "ios": "Settings > Cellular > toggle Cellular Data ON.",
      "android": "Settings > Network & Internet (or Connections) > Mobile Network > toggle Mobile Data ON."
    },
    {
      "step": "Set network mode to 4G/5G preferred",
      "why": "Ensures your phone can connect to modern networks with best coverage.",
      "ios": "Settings > Cellular > Cellular Data Options > Voice & Data > choose 5G Auto (or LTE if 5G Auto is unavailable).",
      "android": "Settings > Network & Internet > Mobile Network > Preferred network type > choose 5G/4G (LTE) preferred. If it’s already on 5G preferred, temporarily set LTE/4G only, wait 20 seconds, then set back to 5G/4G preferred."
    },
    {
      "step": "If SIM status was Missing/No SIM, reseat the SIM",
      "why": "A poorly seated SIM prevents any network registration.",
      "how": "Power the phone OFF. Eject the SIM tray, gently remove the SIM, wipe it with a dry lint-free cloth, reinsert carefully, and power ON."
    },
    {
      "step": "Recheck signal and place a test call",
      "why": "Confirms successful registration.",
      "how": "Wait ~30 seconds after changes, look for signal bars and 4G/5G/LTE, then try a test call and load a webpage on mobile data."
    }
  ],
  "conditional_outcomes": [
    {
      "if": "SIM shows Locked",
      "then": "Do not try random PINs. Tell me, and I’ll transfer you to a specialist to assist with SIM security (PIN/PUK)."
    },
    {
      "if": "SIM shows Active/Ready but still no signal after steps",
      "then": "Tell me your exact network mode setting and we’ll proceed to an APN reset and another quick reboot."
    }
  ],
  "what_to_report_back": "1) SIM status (Active/Ready, Missing, or Locked), 2) Whether Mobile Data is ON, 3) Your current network mode setting, 4) Whether you now see signal bars and if a test call/data works."
}

