messages.content:
{
  "explanation": "Thanks for checking those. Your line is Active and paid, so this looks like a device-side registration issue. Since the SIM is recognized and network mode is 4G/5G preferred, the next most effective steps are to verify/reset APN settings (then reboot), refresh the radio by briefly forcing LTE-only, and rule out Data Saver/VPN interference. If needed, reseat the SIM.",
  "steps_to_try_now_in_order": [
    {
      "step": "Check APN settings, specifically the MMSC",
      "why": "Incorrect/missing APN or MMSC can block connectivity.",
      "how": "Open your APN settings (Android: Settings > Network & Internet/Connections > Mobile Network > Access Point Names. iPhone: Settings > Cellular > Cellular Data Network). Verify an APN is set for your carrier and that an MMSC URL exists."
    },
    {
      "step": "If APN/MMSC looks wrong or you’re unsure, reset APN to default and reboot",
      "why": "Resets any bad entries to known-good defaults; changes only apply after a reboot.",
      "how": "Reset APN to default (Android: in Access Point Names menu > three-dot menu > Reset to default. iPhone: Settings > General > Transfer or Reset > Reset > Reset Network Settings, note this resets Wi‑Fi/VPN settings). After resetting, immediately reboot the phone."
    },
    {
      "step": "Temporarily set LTE/4G only, then switch back to 4G/5G preferred",
      "why": "Forces a fresh registration on a widely available network layer, then re-allows 5G.",
      "how": "Settings > Network & Internet/Connections > Mobile Network > Preferred network type: choose LTE/4G only, wait ~20–30 seconds, then set it back to 4G/5G preferred."
    },
    {
      "step": "Turn off Data Saver and any VPN",
      "why": "Data Saver/VPN can interfere with connectivity in some cases.",
      "how": "Data Saver: Settings > Network & Internet > Data Saver = OFF. VPN: Settings > VPN > disconnect/turn OFF. If using a VPN app, disconnect there as well."
    },
    {
      "step": "If still no signal, power off and reseat the SIM",
      "why": "Physically re-seating often resolves subtle contact issues even when the SIM reports Active.",
      "how": "Power OFF the phone. Eject the SIM tray, remove the SIM, gently wipe with a dry lint-free cloth, reinsert carefully, and power ON."
    },
    {
      "step": "Recheck service",
      "how": "After each change (especially after the APN reset + reboot), wait ~30 seconds, look for signal bars/4G or 5G, place a test call, and try mobile data."
    }
  ],
  "what_to_report_back": [
    "Whether APN had an MMSC URL, or if you reset APN (and confirmed you rebooted afterward).",
    "Result after the LTE-only toggle and then back to 4G/5G preferred.",
    "Whether Data Saver was ON and if any VPN was active.",
    "Result after reseating the SIM (if needed).",
    "Current status bar: any signal bars and 4G/5G/LTE indicator; whether a test call and mobile data now work."
  ],
  "next_if_still_no_service": "If these steps don’t restore service, I’ll escalate you to a specialist, as it may indicate a deeper provisioning or hardware issue."
}

