messages.content:
{
  "thought_process": "You now have strong 5G signal and fresh high‑speed data, but there’s still no data throughput. That points to a stuck/failed data session (PDP context) or a roaming attach quirk. The fastest fixes are to refresh the data/roaming sessions and, if needed, operate on stable LTE (4G) instead of 5G while roaming. We’ll also double‑check that no VPN/Data Saver is sneaking back on.",
  "do_these_steps_in_order": [
    {
      "step": "Refresh the data session",
      "actions": [
        "toggle_data OFF and wait 15 seconds",
        "toggle_data ON"
      ],
      "why": "Forces a fresh IP session which often fixes “No Connection” despite good signal."
    },
    {
      "step": "Refresh roaming permission on device",
      "actions": [
        "toggle_roaming OFF and wait 10 seconds",
        "toggle_roaming ON"
      ],
      "why": "Re-requests data access with the roaming partner."
    },
    {
      "step": "Prefer LTE temporarily",
      "actions": [
        "set_network_mode_preference to 4g_only",
        "wait ~20 seconds and confirm you see 4G/LTE on the status bar"
      ],
      "why": "Some roaming partners show 5G signal but don’t pass data. LTE is typically the most reliable for roaming data."
    },
    {
      "step": "Verify toggles",
      "actions": [
        "check_vpn_status (ensure VPN is OFF). If ON, use disconnect_vpn.",
        "check_data_restriction_status (ensure Data Saver is OFF). If ON, use toggle_data_saver_mode to turn OFF."
      ],
      "why": "Either can silently block data even with great signal."
    },
    {
      "step": "Retest",
      "actions": [
        "check_network_status (confirm: Mobile Data ON, Roaming ON, Network Type: 4G/LTE, Signal: good+)",
        "run_speed_test and share the category/Mbps"
      ]
    },
    {
      "step": "If speed test still says “No Connection”: reseat SIM and reboot",
      "actions": [
        "reseat_sim_card",
        "reboot_device"
      ],
      "why": "Clears SIM/registration state and forces a clean network re-attach."
    },
    {
      "step": "After reboot",
      "actions": [
        "Keep Wi‑Fi OFF and VPN OFF",
        "Ensure Mobile Data ON and Data Roaming ON",
        "Stay on 4g_only for the test",
        "run_speed_test again"
      ]
    }
  ],
  "please_report_back": [
    "After Step 5 (and again after Step 7 if needed): What does check_network_status show (signal strength, network type, data ON, roaming ON)?",
    "Speed test result category and any Mbps shown."
