messages.content:
{
  "explanation": "You now have strong 5G with data and roaming ON, so MMS should work. Since it’s still stuck, the next most common blockers while abroad are Wi‑Fi Calling, VPN, Data Saver, or missing messaging app permissions. We’ll rule these out in order, testing after each change. If those don’t resolve it, we’ll refresh APN and reboot.",
  "steps_in_order": [
    {
      "step": 1,
      "check": "Wi‑Fi Calling",
      "do": [
        "Run check_wifi_calling_status and paste the result.",
        "If it says Wi‑Fi Calling is ON, run toggle_wifi_calling to turn it OFF."
      ],
      "reason": "Some roaming partners don’t support MMS over Wi‑Fi Calling. Turning it OFF ensures MMS uses mobile data.",
      "retest": "Try sending a small MMS again. Report the result."
    },
    {
      "step": 2,
      "check": "VPN",
      "do": [
        "Run check_vpn_status and paste the result.",
        "If a VPN is connected, run disconnect_vpn."
      ],
      "reason": "VPNs can break MMS routing while roaming.",
      "retest": "Try sending the MMS again. Report the result."
    },
    {
      "step": 3,
      "check": "Data Saver",
      "do": [
        "Run check_data_restriction_status and paste the result.",
        "If Data Saver is ON, run toggle_data_saver_mode to turn it OFF."
      ],
      "reason": "Data Saver can interfere with MMS background data.",
      "retest": "Try the MMS again. Report the result."
    },
    {
      "step": 4,
      "check": "Messaging app permissions",
      "do": [
        "Run check_app_permissions with app_name=\"messaging\" and paste the result.",
        "If “storage” or “sms” are missing, run grant_app_permission for each missing one (permission=\"storage\" and permission=\"sms\")."
      ],
      "reason": "The app needs storage and SMS permissions to send/attach media.",
      "retest": "Try the MMS again. Report the result."
    },
    {
      "step": 5,
      "check": "Connection quality",
      "do": [
        "Run run_speed_test and paste the result."
      ],
      "reason": "Confirms mobile data is actually passing traffic. Even slow speeds usually work for MMS, but “no connection/unknown” indicates a data path issue.",
      "if_no_connection_or_unknown": [
        "Toggle mobile data OFF, then ON (run toggle_data twice).",
        "Wait ~15 seconds on 4G/5G, then run run_speed_test again and try the MMS once more."
      ]
    },
    {
      "step": 6,
      "check": "APN refresh (only if still failing after steps 1–5)",
      "do": [
        "Run reset_apn_settings.",
        "Then run reboot_device to apply changes.",
        "After reboot, ensure Wi‑Fi is OFF, Mobile Data ON, Data Roaming ON (re-run check_network_status if needed), and try sending the MMS again."
      ],
      "reason": "A stale APN profile can cause MMS to hang even when the MMSC looks correct."
    }
  ],
  "what_to_share_back": [
    "Outputs of: check_wifi_calling_status, check_vpn_status, check_data_restriction_status, check_app_permissions(app_name=\"messaging\"), run_speed_test.",
    "Whether each re-test MMS sent or stayed on “sending.”",
    "If we do Step 6: confirmation that APN was reset and the phone rebooted, plus the post-reboot MMS result."
  ],
  "keep_in_mind": [
    "Keep Wi‑Fi OFF during testing so MMS uses mobile data.",
    "Stay on network mode 4g_5g_preferred.",
    "Data Roaming should remain ON."
  ],
  "optional_info_request": "Yes, please share your phone model and the messaging app you’re using (e.g., Google Messages, Samsung Messages, iMessage). That can help if we need device-specific guidance."
}

