messages.content:
{
  "confirmation": "Yes—please reseat the SIM now.",
  "why": "Your phone reports “No SIM card detected,” which prevents any network registration. Reseating often restores SIM detection.",
  "step_by_step": [
    {
      "step": "Reseat the SIM",
      "options": [
        "If you can perform the action directly: use reseat_sim_card on the phone.",
        "Physical method: Power the phone OFF. Use the SIM eject tool/paperclip to remove the tray. Ensure the SIM is oriented correctly (notches aligned, gold contacts facing the correct side), lightly dust it off (no liquids), seat it flat in the tray, and reinsert fully. Power the phone back ON."
      ]
    },
    {
      "step": "Check SIM status again",
      "action": "check_sim_status",
      "tell_me": "Does it show Active, Missing, or Locked?"
    },
    {
      "step": "If SIM is Active",
      "actions": [
        "toggle_airplane_mode ON for ~10 seconds, then OFF (network refresh).",
        "check_network_status.",
        "If Mobile Data = OFF: toggle_data to ON.",
        "Since you’re abroad: toggle_roaming to ON.",
        "With Wi‑Fi OFF, open a website to confirm data works; then try sending an MMS."
      ]
    },
    {
      "step": "If SIM is still Missing",
      "actions": [
        "reboot_device (full restart).",
        "After reboot, run check_sim_status again and report the result."
      ]
    },
    {
      "step": "If SIM remains Missing after reboot",
      "next": "Tell me immediately. That likely indicates a SIM or tray issue we can’t resolve remotely, and I’ll proceed with the next steps."
    }
  ],
  "what_to_report_back": [
    "Result of check_sim_status after reseating (Active/Missing/Locked).",
    "If Active: whether you see signal bars/network type, and whether web browsing and MMS work.",
    "If Missing after reboot: confirm so I can take the next action."
  ],
  "notes": [
    "If at any point the SIM shows Locked (PIN/PUK), do not guess; tell me and I’ll escalate per policy.",
    "I’ve already enabled international roaming on your line; once the SIM is detected, we’ll make sure data and roaming are ON on the phone for MMS abroad."
  ]
}

