messages.content:
{
  "summary": "Thanks for the detailed checks. Your line is active with data available, mobile data works well, SMS works, Wi‑Fi Calling is OFF, Data Saver is OFF, no VPN, APN shows an MMSC, and you’re on 4G/5G. That strongly points to a device/app-layer issue rather than the network. We’ll try a few final, targeted resets and a built-in MMS diagnostic.",
  "steps_in_order": [
    {
      "step": "Refresh the mobile data session",
      "why": "A stale data session can block MMS even when browsing works.",
      "how": [
        "Turn Mobile Data OFF (Settings > Network/Cellular). Wait 10–15 seconds.",
        "Turn Mobile Data ON again.",
        "With Wi‑Fi still OFF, try sending one small photo MMS to yourself.",
        "Tell me what happens."
      ]
    },
    {
      "step": "Reseat the SIM, then reboot",
      "why": "Resets the radio/SIM handshake that MMS relies on.",
      "how": [
        "Power the phone OFF.",
        "Remove the SIM tray, reinsert the SIM firmly.",
        "Power the phone ON.",
        "Keep Wi‑Fi OFF, Mobile Data ON, and try one MMS again.",
        "Report the result."
      ]
    },
    {
      "step": "Run the MMS capability check",
      "why": "Confirms if the messaging app reports it can send MMS.",
      "how": [
        "On your phone, run can_send_mms for the messaging app (or try its built-in MMS test if available).",
        "Share the result (can/cannot send MMS)."
      ]
    },
    {
      "step": "Explicitly verify app permissions one more time",
      "why": "MMS needs Storage/Media access and SMS permissions.",
      "how": [
        "Settings > Apps > Messaging > Permissions.",
        "Ensure Storage/Photos/Media is Allowed. If you see SMS/Messages permission, set it to Allow.",
        "Try sending an MMS again and report what happens."
      ]
    }
  ],
  "what_happens_next": "If MMS still won’t send after these steps, we’ve exhausted all device-side and account-side fixes available here. I will transfer you to a human technical specialist who can perform deeper MMS tracing and APN/MMSC verification.",
  "questions": [
    "After toggling Mobile Data OFF/ON, did the MMS send?",
    "After reseating the SIM and rebooting, did the MMS send?",
    "What was the can_send_mms result?",
    "After rechecking permissions, any change when sending MMS?"
  ]
}

