messages.content:
{
  "reassurance": "You didn’t do anything wrong. When you change radio settings abroad, it’s common to briefly see “No Signal.” We’ll bring it back step by step.",
  "what_im_thinking": [
    "Your line is active, roaming is enabled, and you have extra data. So this looks like the phone just hasn’t registered to a local French network yet.",
    "A quick radio refresh usually fixes this. If not, we’ll try a reboot and, if needed, manually pick a local carrier (Orange, SFR, Bouygues, or Free)."
  ],
  "step_1_quick_refresh": {
    "why": "Toggling Airplane Mode forces the phone to drop and re-scan for available networks.",
    "android_steps": [
      "Swipe down from the top of the screen twice to open Quick Settings.",
      "Tap the airplane icon to turn Airplane Mode ON.",
      "Wait 10 seconds.",
      "Tap the airplane icon again to turn Airplane Mode OFF.",
      "Wait 30–60 seconds for signal bars and a network type (4G/5G/LTE) to appear. You might see an ‘R’ or ‘roaming’ icon—that’s normal in France."
    ],
    "safe": "This won’t erase anything on your phone."
  },
  "if_no_signal_after_step_1": {
    "step_2_reboot": {
      "why": "A full restart refreshes all network services.",
      "how": [
        "Hold the Power button (on some phones Power + Volume Down) until the power menu appears.",
        "Tap Restart (or Power off, then turn it back on).",
        "After reboot, give it 1–2 minutes to register to the network."
      ]
    }
  },
  "if_still_no_signal_after_reboot": {
    "step_3_manual_network_selection": {
      "why": "Sometimes automatic selection struggles abroad; picking a partner network manually helps.",
      "android_steps": [
        "Open Settings → Network & Internet (or Connections) → Mobile network.",
        "Tap Network operators (you may need to turn off ‘Select automatically’).",
        "Tap Search networks.",
        "When the list appears, pick one of these if available: Orange F, SFR, Bouygues Telecom, or Free Mobile.",
        "If the first one fails to register, try the next."
      ]
    },
    "step_4_check_network_mode": {
      "why": "Ensures the phone can use 4G/5G networks available in France.",
      "android_steps": [
        "In Mobile network, tap Preferred network type.",
        "Choose 4G/5G (avoid 2G/3G)."
      ]
    }
  },
  "what_to_report_back": [
    "After Step 1 (toggle Airplane Mode), did any signal bars or a network type (4G/5G/LTE) appear?",
    "If you rebooted, did the phone show signal after 1–2 minutes?",
    "If you tried manual selection, which networks did you see and what happened when you chose one?"
  ],
  "next_after_signal_returns": [
    "Confirm Mobile data and Data roaming are ON (they should be).",
    "Try sending a small photo (MMS) to one contact.",
    "If you want, briefly turn Wi‑Fi OFF and load example.com to confirm data, then turn Wi‑Fi back ON."
  ],
  "promise": "I’ll stay with you through each step. Let me know what you see after Step 1, and we’ll proceed together."
}

