messages.content:
{
  "thought_process": "Great find—lack of SMS and storage permissions is a common MMS blocker. Now that you’ve allowed them, there’s a good chance MMS will work. If it still doesn’t, we’ll check a few remaining phone settings that can silently block MMS. We won’t repeat steps we’ve already done unless there’s a specific reason.",
  "what_to_expect_now": {
    "send_test": "Please try sending a small photo now. Give it up to 30–60 seconds.",
    "what_to_watch": [
      "Does it show Sending… then Sent?",
      "Does it get stuck on Sending… or show Not sent?"
    ]
  },
  "if_still_not_sending": {
    "step_1_set_default_sms_app": {
      "why": "Android must use a designated default SMS app for MMS.",
      "android_steps": [
        "Open Settings.",
        "Tap Apps.",
        "Tap Default apps.",
        "Tap SMS app and select Messages (or the texting app you use)."
      ],
      "then_test": "Open Messages and try sending a small photo again."
    },
    "step_2_allow_background_data_for_messages": {
      "why": "MMS may need background data.",
      "android_steps": [
        "Open Settings > Apps > Messages (your texting app).",
        "Tap Mobile data & Wi‑Fi (or Data usage).",
        "Turn ON Background data.",
        "If you see Allow data usage while Data Saver is on, turn that ON too."
      ],
      "then_test": "Try sending a small photo again."
    },
    "step_3_dual_sim_check_if_applicable": {
      "why": "If the phone has two SIMs, MMS must use the SIM with mobile data (your 555-123-2002 line).",
      "android_steps": [
        "Open Settings > Network & Internet (or Connections).",
        "Tap SIMs (or Mobile network).",
        "Ensure your 555-123-2002 line is set as the Mobile data SIM and as the default for SMS."
      ],
      "then_test": "Try sending a small photo again."
    },
    "step_4_verify_mmsc_in_apn": {
      "why": "MMS needs the MMSC server URL in your APN. We reset APN already, but let’s verify it populated.",
      "android_steps": [
        "Open Settings > Network & Internet (or Connections) > Mobile network.",
        "Tap Access Point Names (APN).",
        "Tap the active APN (the one with the filled dot).",
        "Find the MMSC field and confirm it contains a URL (not empty)."
      ],
      "if_mmsc_empty": [
        "Tap the menu (⋮) and Reset to default again.",
        "Restart the phone.",
        "After restart, confirm Mobile data and Data roaming are ON and that you see 4G/LTE/5G.",
        "Try sending a small photo again."
      ]
    }
  },
  "reassurance": {
    "safety": "You’re doing everything right, and none of these steps delete your photos or messages.",
    "progress": "We’ve ruled out roaming, data balance, network mode, APN defaults, Wi‑Fi/Wi‑Fi Calling, VPN, and Data Saver. Permissions were missing and are now enabled—often that’s the key fix."
  },
  "requests": [
    "First, please try sending a small photo now that permissions are granted and tell me exactly what happens.",
    "If it still won’t send, proceed with Step 1 (Default SMS app), test, then Step 2 (Background data), test, then Step 3 (Dual SIM) if applicable, and Step 4 (verify MMSC).",
    "After each step, let me know the result so I can guide you precisely from there."
  ]
}

