messages.content:
{
  "status_summary": "Your line is active, you now have excellent 5G signal, mobile data is ON, Wi‑Fi Calling is OFF, and an MMSC URL is present in APN. The next step is to verify whether the device/app reports MMS as ready.",
  "thought_process": "When connectivity looks good but MMS still fails, the most common remaining causes are (1) the device/app reports MMS not ready, (2) APN parameters other than the MMSC need a reset, (3) the messaging app is missing required permissions, (4) data restrictions (Data Saver) or VPN interference.",
  "next_action": {
    "step": "Check MMS readiness",
    "what_to_do": "Run can_send_mms on your phone.",
    "what_to_share_back": "Please provide the exact result."
  },
  "if_can_send_mms_is_not_ready": [
    {
      "step": "Reset APN settings",
      "why": "Even with a correct-looking MMSC, other APN fields can block MMS.",
      "what_to_do": "Run reset_apn_settings."
    },
    {
      "step": "Apply changes",
      "why": "APN resets require a restart to fully apply.",
      "what_to_do": "Run reboot_device."
    },
    {
      "step": "Re-check MMS readiness",
      "what_to_do": "After the phone restarts, run can_send_mms again and share the exact result."
    }
  ],
  "if_still_failing_after_apn_reset": [
    {
      "step": "Verify messaging app permissions",
      "why": "MMS needs storage and SMS permissions.",
      "what_to_do": "Run check_app_permissions with app_name set to \"messaging\".",
      "what_to_share_back": "List of granted permissions.",
      "fix_if_missing": [
        {
          "what_to_do": "Run grant_app_permission with app_name \"messaging\" and permission \"storage\"."
        },
        {
          "what_to_do": "Run grant_app_permission with app_name \"messaging\" and permission \"sms\"."
        }
      ]
    },
    {
      "step": "Check data restrictions",
      "why": "Data Saver can interfere with MMS.",
      "what_to_do": "Run check_data_restriction_status.",
      "fix_if_needed": "If Data Saver is ON, run toggle_data_saver_mode to turn it OFF."
    },
    {
      "step": "Check VPN status",
      "why": "Some VPNs interfere with MMS/data.",
      "what_to_do": "Run check_vpn_status.",
      "fix_if_needed": "If a VPN is connected, run disconnect_vpn."
    },
    {
      "step": "Optional throughput check",
      "why": "Confirms data is usable if MMS still reports not ready.",
      "what_to_do": "Run run_speed_test and share the result."
    }
  ],
  "please_reply_with": "The exact output of can_send_mms. Based on that, I’ll guide you to the next specific step."
}

