messages.content:
{
  "summary": "Your phone shows 5G with excellent signal and mobile data ON, but the speed test says No Connection. That usually means data isn’t actually passing. The two most common causes now are: (1) you’re in a roaming area but your line’s roaming isn’t enabled on our side, or (2) a stuck data session on the device/SIM.",
  "quick_question": "Are you currently traveling outside your usual home area or internationally (e.g., out of state/country)?",
  "why_ask": "Your device has Data Roaming ON, but your line is not roaming-enabled on our side. If you are traveling, that would block data and MMS even though you see 5G.",
  "offer": "If you are traveling, I can enable roaming on your line right now at no cost. Please say “Yes, enable roaming.”",
  "in_parallel_device_fixes": [
    {
      "step": 1,
      "name": "Refresh the mobile data session",
      "what_to_do_on_phone": [
        "Run: toggle_data (turn it OFF). Wait 10 seconds.",
        "Run: toggle_data again (turn it ON)."
      ],
      "then_test": [
        "Run: run_speed_test and tell me the result.",
        "Try sending a small picture message to your own number."
      ]
    },
    {
      "step": 2,
      "name": "Reseat SIM and reboot (if Step 1 doesn’t restore data)",
      "what_to_do_on_phone": [
        "Run: reseat_sim_card",
        "Then run: reboot_device"
      ],
      "after_reboot": [
        "Run: check_network_status (confirm 4G/5G, data ON).",
        "Run: run_speed_test again and share the result.",
        "Try sending an MMS again."
      ]
    }
  ],
  "what_to_reply_with": [
    "Whether you are traveling (Yes/No). If Yes, I’ll enable roaming immediately.",
    "The speed test result after Step 1 (and Step 2 if needed).",
    "Whether the MMS sends after these steps, or any error you see."
  ],
  "reassurance": "None of these steps will delete your photos or data. We’ll either restore data flow with the toggles/reseat, or, if you’re traveling, enabling roaming on your line will solve the data/MMS block."
}

