messages.content:
{
  "empathy": "Thanks for sticking with this, John. We’ve got strong 5G signal now, so we’re close. MMS usually fails at this point due to a settings issue (APN/MMSC), Wi‑Fi Calling interaction, Data Saver/VPN, or app permissions. We’ll fix those step by step. Nothing here will erase your photos or data.",
  "thought_process": "MMS needs mobile data plus the correct APN/MMSC. With 5G bars and data ON, the most common remaining culprit is APN/MMSC. Per best practice, we’ll reset APN to default and reboot (required), then rule out Wi‑Fi Calling, Data Saver, VPN issues, and confirm the Messages app has Storage and SMS permissions.",
  "steps_in_order": [
    {
      "step": "Quick data sanity check",
      "why": "Confirms mobile data truly works before changing settings.",
      "how": [
        "Keep Wi‑Fi OFF for this test.",
        "Open Chrome and go to example.com. Tell me if it loads."
      ]
    },
    {
      "step": "Turn OFF Wi‑Fi Calling (temporarily)",
      "why": "Wi‑Fi Calling can interfere with MMS on some devices/carriers.",
      "how": [
        "Settings > Network & internet (or Connections) > Mobile network (or SIMs).",
        "Find Wi‑Fi Calling and turn it OFF."
      ]
    },
    {
      "step": "Make sure Data Saver is OFF",
      "why": "Data Saver can block background data needed by MMS.",
      "how": [
        "Settings > Network & internet > Data Saver.",
        "Turn Data Saver OFF."
      ]
    },
    {
      "step": "Ensure no VPN is active",
      "why": "A VPN can block/slow MMS traffic.",
      "how": [
        "Settings > Network & internet > VPN.",
        "If a VPN shows Connected, tap it and Disconnect."
      ]
    },
    {
      "step": "Reset APN to default (then reboot)",
      "why": "Incorrect or missing MMSC in APN is a top cause of MMS failure.",
      "how": [
        "Settings > Network & internet > Mobile network (or SIMs) > Access Point Names.",
        "Tap the three‑dot menu (or More) > Reset to default.",
        "Now restart the phone: hold the power button > Restart.",
        "After it restarts, wait 1 minute for the network to settle."
      ],
      "after_reboot": [
        "Confirm Mobile data is ON and Wi‑Fi is OFF for testing.",
        "Verify the top shows 4G/LTE/5G (you should still see 5G)."
      ]
    },
    {
      "step": "Test again",
      "why": "Checks if APN reset resolved the MMS configuration.",
      "how": [
        "Open Chrome and go to example.com (with Wi‑Fi OFF).",
        "Open Messages and send a small photo to yourself."
      ]
    },
    {
      "step": "Confirm Messages app permissions",
      "why": "MMS needs storage/media and SMS permissions.",
      "how": [
        "Settings > Apps > Messages.",
        "Permissions > Allow: Photos and videos (or Files and media) AND SMS.",
        "Also check Mobile data & Wi‑Fi (or Data usage) > Background data: ON."
      ]
    },
    {
      "step": "Try sending a picture again",
      "why": "Verifies after permissions that MMS can send.",
      "how": [
        "Open Messages and send a small photo to yourself or the same contact."
      ]
    }
  ],
  "important_notes": [
    "All steps are safe; none delete photos or personal data.",
    "A restart is required only after the APN reset (Step 5).",
    "Once MMS works, you can turn Wi‑Fi back ON."
  ],
  "what_to_report_back": [
    "Did example.com load over mobile data (before and after the APN reset)?",
    "Was Wi‑Fi Calling ON, and did you turn it OFF?",
    "Was Data Saver ON, and did you turn it OFF?",
    "Any VPN connected?",
    "After Reset APN + Restart: do you still see 4G/LTE/5G and full bars?",
    "Did the picture message send after these steps? If not, what exact message appears?"
  ],
  "next_if_still_failing_after_all_steps": "Tell me the results. If MMS still won’t send after APN reset + reboot and permissions are correct, I’ll escalate this to a human agent to check deeper provisioning or device-specific factors."
}

