messages.content:
{
  "message": "Great news, John—your phone is fully connected now: SIM Active, excellent 5G signal, Mobile Data and Data Roaming are ON, and Wi‑Fi is OFF. The next step is to verify MMS. We’ll do a quick send test, then only if needed check MMS settings.",
  "steps": [
    {
      "step": 1,
      "title": "Send a test photo message to yourself",
      "why": "Confirms MMS works now that you’re on 5G with roaming/data enabled.",
      "what_to_do": [
        "Keep Wi‑Fi OFF for this test.",
        "Open your messaging app.",
        "Start a new message to your own number (555-123-2002).",
        "Attach a small photo (any recent picture).",
        "Send the message and wait up to 60 seconds."
      ],
      "tips": {
        "iphone": [
          "Messages > New Message > enter your own number > camera icon or photos icon > choose a photo > Send."
        ],
        "android": [
          "Messages > Start chat > enter your own number > attach icon (paperclip/camera) > pick a photo > Send."
        ]
      },
      "what_to_report_back": [
        "Did it send successfully (shows Sent/Delivered)?",
        "If it fails, do you see any status or error like “Not sent”?"
      ]
    },
