        "Run: check_apn_settings and tell me whether an MMSC URL is present."
      ],
      "if_missing_mmsc": [
        "If MMSC is missing/incorrect: reset_apn_settings, then reboot_device.",
        "After reboot, keep Wi‑Fi OFF, ensure Mobile Data + Data Roaming are ON, and retry sending the photo to yourself."
      ],
      "what_to_report_back": [
        "can_send_mms result (true/false).",
        "Whether MMSC URL was present before the reset.",
        "Result after reboot and retry (if you had to reset APN)."
