      "title": "If still failing after APN reset",
      "why": "Wi‑Fi Calling can sometimes interfere with MMS routing when abroad.",
      "what_to_do": [
        "Run: check_wifi_calling_status.",
        "If it shows ON: toggle_wifi_calling to turn it OFF, then retry sending the photo."
      ],
      "what_to_report_back": [
        "Wi‑Fi Calling status and whether MMS sent after turning it OFF."
      ]
    },
    {
      "step": 4,
      "title": "If still failing: messaging app permissions",
      "why": "The app needs storage and SMS permissions to send MMS.",
      "what_to_do": [
        "Run: check_app_permissions for your messaging app (name is usually “Messages” or “Messaging”).",
        "If storage or sms are missing: grant_app_permission for storage and sms.",
        "Retry sending the photo."
      ],
      "what_to_report_back": [
        "Which permissions were missing and the result after granting."
      ]
    },
    {
      "step": 5,
      "title": "If still failing: carrier-side roaming refresh",
      "why": "Re-provisions roaming on our network side as a final step.",
      "what_I_can_do": [
        "Since you previously approved, I can refresh roaming on your line (brief, safe).",
        "After I do that, you’ll toggle Airplane Mode ON for 10 seconds and OFF, then retry the MMS."
      ],
      "what_to_report_back": [
        "Let me know if you want me to proceed with the roaming refresh now."
      ]
    }
  ],
  "questions": [
    "Please do Step 1 now (send a photo to yourself with Wi‑Fi OFF). Did it send successfully?",
    "If it didn’t send, please share the results of can_send_mms and whether the APN shows an MMSC URL."
  ],
  "reassurance": "You’re connected with excellent 5G signal; in most cases MMS will send now. The remaining steps are safe and reversible if we need them. Once it works, you can turn Wi‑Fi back ON whenever you like.",
